// ==== 实现区 ====
void ASL_WeaponBase::TriggerHitFeedback(AActor* InTarget, const FVector& InHitLocation, EHitSeverity InSeverity)
{
    if (!HasAuthority() || !InTarget) return;

    FHitFeedbackData Data;
    Data.Severity = InSeverity;
    Data.InstigatorActor = OwningCharacter;
    Data.TargetActor = InTarget;
    Data.HitLocation = InHitLocation;
    Data.HitStopDuration = GetHitStopDuration(InSeverity);

    // ShakeScale：轻击 0.5, 重击 1.0, 处决 2.0
    switch (InSeverity)
    {
    case EHitSeverity::Light:   Data.ShakeScale = 0.5f; break;
    case EHitSeverity::Heavy:   Data.ShakeScale = 1.0f; break;
    case EHitSeverity::Execute: Data.ShakeScale = 2.0f; break;
    case EHitSeverity::Parry:   Data.ShakeScale = 1.2f; break;
    case EHitSeverity::Block:   Data.ShakeScale = 0.3f; break;
    default:                    Data.ShakeScale = 1.0f; break;
    }

    // Multicast 到所有客户端
    Multicast_OnHitFeedback(Data);
}

float ASL_WeaponBase::GetHitStopDuration(EHitSeverity InSeverity) const
{
    // 可考虑 WeaponData.WeaponType 做差异，但 Phase 2 先用固定值
    switch (InSeverity)
    {
    case EHitSeverity::Light:   return 0.10f;   // 6帧@60fps
    case EHitSeverity::Heavy:   return 0.15f;   // 9帧
    case EHitSeverity::Execute: return 0.30f;   // 18帧
    case EHitSeverity::Parry:   return 0.25f;   // 15帧
    case EHitSeverity::Block:   return 0.08f;   // 5帧
    default:                    return 0.10f;
    }
}

void ASL_WeaponBase::RestoreActorTimeDilation(AActor* InActor)
{
    if (InActor) InActor->CustomTimeDilation = 1.0f;
}

void ASL_WeaponBase::Multicast_OnHitFeedback_Implementation(const FHitFeedbackData& InData)
{
    // === 1. Hit Stop ===
    const float StopDuration = InData.HitStopDuration;

    if (InData.InstigatorActor)
    {
        InData.InstigatorActor->CustomTimeDilation = 0.001f;
        FTimerHandle& Handle = HitStopTimerHandles.FindOrAdd(InData.InstigatorActor);
        GetWorldTimerManager().ClearTimer(Handle);
        GetWorldTimerManager().SetTimer(Handle, FTimerDelegate::CreateUObject(this,
            &ASL_WeaponBase::RestoreActorTimeDilation, InData.InstigatorActor),
            StopDuration, false);
    }

    if (InData.TargetActor)
    {
        InData.TargetActor->CustomTimeDilation = 0.001f;
        FTimerHandle& Handle = HitStopTimerHandles.FindOrAdd(InData.TargetActor);
        GetWorldTimerManager().ClearTimer(Handle);
        GetWorldTimerManager().SetTimer(Handle, FTimerDelegate::CreateUObject(this,
            &ASL_WeaponBase::RestoreActorTimeDilation, InData.TargetActor),
            StopDuration, false);
    }

    // === 2. Camera Shake + 屏幕效果（仅本机控制的角色参与） ===
    ACharacter* LocalChar = UGameplayStatics::GetPlayerCharacter(GetWorld(), 0);
    if (!LocalChar) return;

    bool bIsLocalInstigator = (LocalChar == InData.InstigatorActor);
    bool bIsLocalTarget    = (LocalChar == InData.TargetActor);

    if (!bIsLocalInstigator && !bIsLocalTarget) return;

    APlayerController* PC = Cast<APlayerController>(LocalChar->GetController());
    ASL_PlayerControllerBase* SLPC = Cast<ASL_PlayerControllerBase>(PC);
    if (!SLPC) return;

    SLPC->PlayHitCameraShake(InData.Severity, InData.ShakeScale);
    SLPC->PlayHitScreenEffect(InData.Severity);
}
