**⑩ `SL_PlayerControllerBase.cpp`** — 实现：

```cpp
void ASL_PlayerControllerBase::PlayHitCameraShake(EHitSeverity InSeverity, float InShakeScale)
{
    APlayerCameraManager* CamMgr = PlayerCameraManager;
    if (!CamMgr) return;

    TSubclassOf<UCameraShakeBase> ShakeClass = USL_CameraShake_Hit::StaticClass();
    if (!ShakeClass) return;

    CamMgr->StartCameraShake(ShakeClass, InShakeScale);
}

void ASL_PlayerControllerBase::PlayHitScreenEffect(EHitSeverity InSeverity)
{
    APlayerCameraManager* CamMgr = PlayerCameraManager;
    if (!CamMgr) return;

    FLinearColor FlashColor;
    float FlashIntensity;
    float Duration;

    switch (InSeverity)
    {
    case EHitSeverity::Light:
        FlashColor = FLinearColor::White;
        FlashIntensity = 0.15f;
        Duration = 0.08f;
        break;
    case EHitSeverity::Heavy:
        FlashColor = FLinearColor::White;
        FlashIntensity = 0.4f;
        Duration = 0.12f;
        break;
    case EHitSeverity::Execute:
        FlashColor = FLinearColor::White;
        FlashIntensity = 0.8f;
        Duration = 0.25f;
        break;
    case EHitSeverity::Parry:
        FlashColor = FLinearColor::White;
        FlashIntensity = 0.6f;
        Duration = 0.15f;
        break;
    case EHitSeverity::Block:
        FlashColor = FLinearColor::White;
        FlashIntensity = 0.1f;
        Duration = 0.05f;
        break;
    default:
        return;
    }

    // 使用 PlayerCameraManager 的 StartCameraFade 实现闪屏
    // 先闪入（瞬间不透明），再闪出（淡出）
    CamMgr->StartCameraFade(0.0f, 1.0f, 0.02f, FlashColor, false, true);
    FTimerHandle FadeOutHandle;
    GetWorldTimerManager().SetTimer(FadeOutHandle, FTimerDelegate::CreateWeakLambda(this,
        [this, CamMgr, Duration]()
        {
            CamMgr->StartCameraFade(1.0f, 0.0f, Duration * 0.5f, FLinearColor::White, false, false);
        }), 0.03f, false);
}
