void ASL_PlayerControllerBase::PlayHitCameraShake(EHitSeverity InSeverity, float InShakeScale)
{
	APlayerCameraManager* CamMgr = PlayerCameraManager;
	if (!CamMgr) return;

	TSubclassOf<UCameraShakeBase> ShakeClass = USL_CameraShake_Hit::StaticClass();
	if (!ShakeClass) return;

	CamMgr->StartCameraShake(ShakeClass, InShakeScale);
}

void ASL_PlayerControllerBase::PlayHitScreenEffect(EHitSeverity InSeverity)
{
	APlayerCameraManager* CamMgr = PlayerCameraManager;
	if (!CamMgr) return;

	// 通过 StartCameraFade 实现瞬闪
	// 原理：先快速淡入到半透明色，再淡出

	float FadeInDuration = 0.02f;
	float HoldDuration;
	float FadeOutDuration;
	FLinearColor FlashColor;

	switch (InSeverity)
	{
	case EHitSeverity::Light:
		FlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.15f);  // 轻度白闪
		HoldDuration = 0.04f;
		FadeOutDuration = 0.06f;
		break;
	case EHitSeverity::Heavy:
		FlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.4f);   // 中度白闪
		HoldDuration = 0.06f;
		FadeOutDuration = 0.10f;
		break;
	case EHitSeverity::Execute:
		FlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.8f);   // 强白闪
		HoldDuration = 0.15f;
		FadeOutDuration = 0.20f;
		break;
	case EHitSeverity::Parry:
		FlashColor = FLinearColor(1.0f, 1.0f, 0.3f, 0.6f);   // 金色闪
		HoldDuration = 0.10f;
		FadeOutDuration = 0.15f;
		break;
	case EHitSeverity::Block:
		FlashColor = FLinearColor(0.5f, 0.5f, 0.5f, 0.1f);   // 灰色微闪
		HoldDuration = 0.02f;
		FadeOutDuration = 0.04f;
		break;
	default:
		return;
	}

	// Step 1: 快速淡入到闪色（bHoldWhenFinished = true 保持颜色）
	CamMgr->StartCameraFade(0.0f, 1.0f, FadeInDuration, FlashColor, false, true);

	// Step 2: 短暂保持后淡出回到正常
	FTimerHandle FadeOutHandle;
	float TotalHold = FadeInDuration + HoldDuration;
	GetWorldTimerManager().SetTimer(FadeOutHandle, FTimerDelegate::CreateWeakLambda(this,
		[this, CamMgr, FadeOutDuration]()
		{
			CamMgr->StartCameraFade(1.0f, 0.0f, FadeOutDuration, FLinearColor::White, false, false);
		}), TotalHold, false);
}

