    append_impl = """

/************************************************************************/
/*                       打击感：命中反馈实现                              */
/************************************************************************/

void ASL_WeaponBase::TriggerHitFeedback(AActor* InTarget, const FVector& InHitLocation, EHitSeverity InSeverity)
{
\tif (!HasAuthority() || !InTarget) return;

\tFHitFeedbackData Data;
\tData.Severity = InSeverity;
\tData.InstigatorActor = OwningCharacter;
\tData.TargetActor = InTarget;
\tData.HitLocation = InHitLocation;
\tData.HitStopDuration = GetHitStopDuration(InSeverity);

\tswitch (InSeverity)
\t{
\tcase EHitSeverity::Light:   Data.ShakeScale = 0.5f; break;
\tcase EHitSeverity::Heavy:   Data.ShakeScale = 1.0f; break;
\tcase EHitSeverity::Execute: Data.ShakeScale = 2.0f; break;
\tcase EHitSeverity::Parry:   Data.ShakeScale = 1.2f; break;
\tcase EHitSeverity::Block:   Data.ShakeScale = 0.3f; break;
\tdefault:                    Data.ShakeScale = 1.0f; break;
\t}

\tMulticast_OnHitFeedback(Data);
}

float ASL_WeaponBase::GetHitStopDuration(EHitSeverity InSeverity) const
{
\tswitch (InSeverity)
\t{
\tcase EHitSeverity::Light:   return 0.10f;
\tcase EHitSeverity::Heavy:   return 0.15f;
\tcase EHitSeverity::Execute: return 0.30f;
\tcase EHitSeverity::Parry:   return 0.25f;
\tcase EHitSeverity::Block:   return 0.08f;
\tdefault:                    return 0.10f;
\t}
}

void ASL_WeaponBase::RestoreActorTimeDilation(AActor* InActor)
{
\tif (InActor) InActor->CustomTimeDilation = 1.0f;
}

void ASL_WeaponBase::Multicast_OnHitFeedback_Implementation(const FHitFeedbackData& InData)
{
\t// === 1. Hit Stop ===
\tconst float StopDuration = InData.HitStopDuration;

\tif (InData.InstigatorActor)
\t{
\t\tInData.InstigatorActor->CustomTimeDilation = 0.001f;
\t\tFTimerHandle& Handle = HitStopTimerHandles.FindOrAdd(InData.InstigatorActor);
\t\tGetWorldTimerManager().ClearTimer(Handle);
\t\tGetWorldTimerManager().SetTimer(Handle, FTimerDelegate::CreateUObject(this,
\t\t\t&ASL_WeaponBase::RestoreActorTimeDilation, InData.InstigatorActor),
\t\t\tStopDuration, false);
\t}

\tif (InData.TargetActor)
\t{
\t\tInData.TargetActor->CustomTimeDilation = 0.001f;
\t\tFTimerHandle& Handle = HitStopTimerHandles.FindOrAdd(InData.TargetActor);
\t\tGetWorldTimerManager().ClearTimer(Handle);
\t\tGetWorldTimerManager().SetTimer(Handle, FTimerDelegate::CreateUObject(this,
\t\t\t&ASL_WeaponBase::RestoreActorTimeDilation, InData.TargetActor),
\t\t\tStopDuration, false);
\t}

\t// === 2. Camera Shake + 屏幕效果（仅本机角色） ===
\tACharacter* LocalChar = UGameplayStatics::GetPlayerCharacter(GetWorld(), 0);
\tif (!LocalChar) return;

\tbool bIsLocalInstigator = (LocalChar == InData.InstigatorActor);
\tbool bIsLocalTarget    = (LocalChar == InData.TargetActor);
\tif (!bIsLocalInstigator && !bIsLocalTarget) return;

\tAPlayerController* PC = Cast<APlayerController>(LocalChar->GetController());
\tASL_PlayerControllerBase* SLPC = Cast<ASL_PlayerControllerBase>(PC);
\tif (!SLPC) return;

\tif (bIsLocalInstigator)
\t{
\t\tSLPC->PlayHitCameraShake(InData.Severity, InData.ShakeScale * 0.5f);
\t\tSLPC->PlayHitScreenEffect(InData.Severity);
\t}
\telse if (bIsLocalTarget)
\t{
\t\tSLPC->PlayHitCameraShake(InData.Severity, InData.ShakeScale);
\t\tSLPC->PlayHitScreenEffect(InData.Severity);
\t}
}
"""
    content += append_impl

    with open(filepath, "w", encoding="utf-8") as f:
