void ASL_PlayerControllerBase::PlayHitCameraShake(EHitSeverity InSeverity, float InShakeScale)
{
\tAPlayerCameraManager* CamMgr = PlayerCameraManager;
\tif (!CamMgr) return;

\tTSubclassOf<UCameraShakeBase> ShakeClass = USL_CameraShake_Hit::StaticClass();
\tif (!ShakeClass) return;

\tCamMgr->StartCameraShake(ShakeClass, InShakeScale);
}

void ASL_PlayerControllerBase::PlayHitScreenEffect(EHitSeverity InSeverity)
{
\tAPlayerCameraManager* CamMgr = PlayerCameraManager;
\tif (!CamMgr) return;

\tfloat FadeInDuration = 0.02f;
\tfloat HoldDuration;
\tfloat FadeOutDuration;
\tFLinearColor FlashColor;

\tswitch (InSeverity)
\t{
\tcase EHitSeverity::Light:
\t\tFlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.15f);
\t\tHoldDuration = 0.04f;
\t\tFadeOutDuration = 0.06f;
\t\tbreak;
\tcase EHitSeverity::Heavy:
\t\tFlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.4f);
\t\tHoldDuration = 0.06f;
\t\tFadeOutDuration = 0.10f;
\t\tbreak;
\tcase EHitSeverity::Execute:
\t\tFlashColor = FLinearColor(1.0f, 1.0f, 1.0f, 0.8f);
\t\tHoldDuration = 0.15f;
\t\tFadeOutDuration = 0.20f;
\t\tbreak;
\tcase EHitSeverity::Parry:
\t\tFlashColor = FLinearColor(1.0f, 1.0f, 0.3f, 0.6f);
\t\tHoldDuration = 0.10f;
\t\tFadeOutDuration = 0.15f;
\t\tbreak;
\tcase EHitSeverity::Block:
\t\tFlashColor = FLinearColor(0.5f, 0.5f, 0.5f, 0.1f);
\t\tHoldDuration = 0.02f;
\t\tFadeOutDuration = 0.04f;
\t\tbreak;
\tdefault:
\t\treturn;
\t}

\t// 先快速淡入到闪色（保持）
\tCamMgr->StartCameraFade(0.0f, 1.0f, FadeInDuration, FlashColor, false, true);

\t// 保持后淡出
\tFTimerHandle FadeOutHandle;
\tfloat TotalHold = FadeInDuration + HoldDuration;
\tGetWorldTimerManager().SetTimer(FadeOutHandle, FTimerDelegate::CreateWeakLambda(this,
\t\t[this, CamMgr, FadeOutDuration]()
\t\t{
\t\t\tCamMgr->StartCameraFade(1.0f, 0.0f, FadeOutDuration, FLinearColor::White, false, false);
\t\t}), TotalHold, false);
}
"""
